import React from 'react';

import emotionStyled from '@emotion/styled';

import type { LocalIconProps } from './createSvgIconComponent';

export type IconSize = 'tiny' | 'small' | 'medium' | 'large';

const iconPixelSizes: Record<IconSize, number> = {
  tiny: 12,
  small: 16,
  medium: 24,
  large: 32,
};

export type IconComponent = React.ComponentType<LocalIconProps>;

export interface IconProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  'children' | 'color'
> {
  icon: IconComponent;
  size?: IconSize;
  color?: string;
  notificationVariant?: 'default' | 'brand';
}

interface IconContainerProps {
  $size: IconSize;
}

const IconContainer = emotionStyled('div', {
  shouldForwardProp: (propName) => !['$color', '$size'].includes(propName),
})<IconContainerProps>(({ $size }) => ({
  alignItems: 'center',
  display: 'inline-flex',
  fontSize: iconPixelSizes[$size],
  justifyContent: 'center',
  position: 'relative',
}));

export const Icon = React.forwardRef<HTMLDivElement, IconProps>(
  (
    {
      icon: SvgIcon,
      size = 'medium',
      color,
      notificationVariant,
      role,
      ...props
    },
    forwardedRef,
  ) => {
    const hasAccessibleName = Boolean(
      props['aria-label'] || props['aria-labelledby'],
    );

    return (
      <IconContainer
        {...props}
        ref={forwardedRef}
        style={{ color, ...props.style }}
        $size={size}
        role={role ?? (hasAccessibleName ? 'img' : undefined)}
        aria-hidden={props['aria-hidden'] ?? !hasAccessibleName}
        data-notification-variant={notificationVariant}
      >
        <SvgIcon size="small" aria-hidden />
      </IconContainer>
    );
  },
);

Icon.displayName = 'Icon';
